script:
frappe.ui.form.on('BreakRecords', {
    date: function (frm, cdt, cdn) {
        let row = locals[cdt][cdn];
        let selected_date = row.date;
        let today = frappe.datetime.get_today();

        if (!selected_date) return;

        // 1. Must be today
        if (selected_date !== today) {
            frappe.msgprint("Date must be today's date.");
            frappe.model.set_value(cdt, cdn, "date", "");
            return;
        }

        // 2. Must be within parent start and end of week
        let week_start = frm.doc.week_start_date;
        let week_end = frm.doc.week_end_date;

        if (!week_start || !week_end) {
            frappe.msgprint("Please ensure both Week Start Date and Week End Date are set in the parent form.");
            frappe.model.set_value(cdt, cdn, "date", "");
            return;
        }

        if (
            selected_date < week_start ||
            selected_date > week_end
        ) {
            frappe.msgprint(`Date must be within the week (${week_start} to ${week_end}).`);
            frappe.model.set_value(cdt, cdn, "date", "");
        }


        console.log("log")
    }, 
    

    
   


});



frappe.ui.form.on('Weekly Break Summary', {
    
    validate: function (frm) {
        let has_error = false;

        frm.doc.break_timing_records.forEach(row => {
            if (!row.entry_time) {
                frappe.msgprint({
                    title: "Invalid Break Time",
                    message: `Please select <b>Start of Break</b> for row ${row.idx}`,
                    indicator: "red"
                });
                has_error = true;
            } else if (!row.exit_time) {
                frappe.msgprint({
                    title: "Invalid Break Time",
                    message: `Please select <b>End of Break</b> for row ${row.idx}`,
                    indicator: "red"
                });
                has_error = true;
            } else if (row.entry_time > row.exit_time) {
                frappe.msgprint({
                    title: "Invalid Break Time",
                    message: `End of Break must be after Start of Break in row ${row.idx}`,
                    indicator: "red"
                });
                has_error = true;
            }
        });

        // Prevent saving the form if there's any error
        if (has_error) frappe.validated = false;
    }
});
